import os
from datadog_api_client import ApiClient, Configuration
from datadog_api_client.v1.api.metrics_api import MetricsApi

def compare_metric_series(payload, config=None):
    config = config or {}
    configuration = Configuration()
    configuration.api_key["apiKeyAuth"] = config.get("api_key") or os.environ["DD_API_KEY"]
    configuration.api_key["appKeyAuth"] = config.get("app_key") or os.environ["DD_APP_KEY"]
    site = config.get("site") or os.environ.get("DD_SITE")
    if site:
        configuration.server_variables["site"] = site

    metric = payload["metric"]
    start = int(payload["start"])
    end = int(payload["end"])
    left_scope = payload["left_scope"]
    right_scope = payload["right_scope"]
    aggregator = payload.get("aggregator", "avg")
    rollup = payload.get("rollup")

    def _build_query(scope):
        query = f"{aggregator}:{metric}{{{scope}}}"
        if rollup is not None:
            query += f".rollup({int(rollup)})"
        return query

    def _series_to_points(series):
        pointlist = getattr(series, "pointlist", None) or []
        return [
            {"timestamp": int(p[0]), "value": (None if p[1] is None else float(p[1]))}
            for p in pointlist
        ]

    def _summary(points):
        values = [p["value"] for p in points if p["value"] is not None]
        if not values:
            return {"count": 0, "min": None, "max": None, "avg": None}
        return {
            "count": len(values),
            "min": min(values),
            "max": max(values),
            "avg": sum(values) / len(values),
        }

    with ApiClient(configuration) as api_client:
        api = MetricsApi(api_client)
        left_resp = api.query_metrics(_from=start, to=end, query=_build_query(left_scope))
        right_resp = api.query_metrics(_from=start, to=end, query=_build_query(right_scope))

    left_series = (getattr(left_resp, "series", None) or [None])[0]
    right_series = (getattr(right_resp, "series", None) or [None])[0]
    left_points = _series_to_points(left_series) if left_series else []
    right_points = _series_to_points(right_series) if right_series else []

    result = {
        "provider": "datadog",
        "metric": metric,
        "window": {"start": start, "end": end},
        "left": {
            "scope": left_scope,
            "query": _build_query(left_scope),
            "points": left_points,
            "summary": _summary(left_points),
        },
        "right": {
            "scope": right_scope,
            "query": _build_query(right_scope),
            "points": right_points,
            "summary": _summary(right_points),
        },
        "difference": {
            "avg": (
                None
                if _summary(left_points)["avg"] is None or _summary(right_points)["avg"] is None
                else _summary(left_points)["avg"] - _summary(right_points)["avg"]
            ),
            "min": (
                None
                if _summary(left_points)["min"] is None or _summary(right_points)["min"] is None
                else _summary(left_points)["min"] - _summary(right_points)["min"]
            ),
            "max": (
                None
                if _summary(left_points)["max"] is None or _summary(right_points)["max"] is None
                else _summary(left_points)["max"] - _summary(right_points)["max"]
            ),
        },
    }
    return result
